  for (const r of runs) console.log('  run count', r.count, 'line', lineOf(clean, r.index), clean.slice(r.index, r.index+80).replace(/\n/g,'\\n'));
  if (sw) console.log('  switch distinct', sw.distinct, 'line', lineOf(clean, sw.index));
  else console.log('  switch: none');
}
